         {
           id: "web-languages",
           question: "Which languages commonly run in web browsers?",
           choices: ["JavaScript", "TypeScript", "Swift", "WebAssembly"],
         },
         {
           id: "compiled-languages",
           question: "Which languages are commonly compiled before execution?",
           choices: ["C", "Rust", "Go", "Markdown"],
         },
       ];

       function Choice({ questionId, choice }) {
         const id = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

         return `
           <label class="choice" for="${id}">
             <input id="${id}" name="${questionId}" type="checkbox" value="${choice}">
             <span>${choice}</span>
           </label>
         `;
       }

       function QuizQuestion({ id, question, helpText, choices }) {
         const describedBy = helpText ? ` aria-describedby="${id}-help"` : "";

         return `
           <div class="form-field">
