               <button type="submit">Submit quiz</button>
               <p class="status" id="quiz-status" aria-live="polite"></p>
             </div>
           </form>
         `;
       }

       document.querySelector("#quiz-root").innerHTML = QuizApp({
         questions: quizQuestions,
       });

       document.querySelector("#quiz-form").addEventListener("submit", (event) => {
         event.preventDefault();

         const selectedCount = quizQuestions.reduce(
           (total, { id }) =>
             total + document.querySelectorAll(`input[name="${id}"]:checked`).length,
           0
         );
         const status = document.querySelector("#quiz-status");

         status.textContent = `Quiz submitted. You selected ${selectedCount} answer${
