    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <header class="hero">
        <p class="eyebrow">Multi-select quiz</p>
        <h1>Computer Languages Quiz</h1>
        <p class="intro">
          Choose every answer that applies for each question, then submit your
          responses.
        </p>
      </header>

      <section class="quiz-card" aria-labelledby="quiz-title">
        <h2 id="quiz-title">Test your language knowledge</h2>
        <div id="quiz-root"></div>
      </section>
    </main>

    <script>
      const quizQuestions = [
        {
          id: "language-types",
          question: "Which of these are programming languages?",
          helpText: "Select all choices that are used to write executable programs or scripts.",
          choices: ["Python", "HTML", "JavaScript", "Java"],
        },
        {
          id: "web-languages",
          question: "Which languages commonly run in web browsers?",
          choices: ["JavaScript", "TypeScript", "Swift", "WebAssembly"],
        },
        {
          id: "compiled-languages",
          question: "Which languages are commonly compiled before execution?",
          choices: ["C", "Rust", "Go", "Markdown"],
        },
      ];

      function Choice({ questionId, choice }) {
        const id = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

        return `
          <label class="choice" for="${id}">
            <input id="${id}" name="${questionId}" type="checkbox" value="${choice}">
            <span>${choice}</span>
          </label>
        `;
      }

      function QuizQuestion({ id, question, helpText, choices }) {
        const describedBy = helpText ? ` aria-describedby="${id}-help"` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${question}</legend>
              ${
                helpText
                  ? `<p class="help-text" id="${id}-help">${helpText}</p>`
                  : ""
              }
              <div class="choice-list">
                ${choices.map((choice) => Choice({ questionId: id, choice })).join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function QuizApp({ questions }) {
        return `
          <form class="quiz-form" id="quiz-form" novalidate>
            ${questions.map((question) => QuizQuestion(question)).join("")}
            <div class="actions">
              <button type="submit">Submit quiz</button>
              <p class="status" id="quiz-status" aria-live="polite"></p>
            </div>
          </form>
        `;
      }

      document.querySelector("#quiz-root").innerHTML = QuizApp({
        questions: quizQuestions,
      });

      document.querySelector("#quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const selectedCount = quizQuestions.reduce(
          (total, { id }) =>
            total + document.querySelectorAll(`input[name="${id}"]:checked`).length,
          0
        );
        const status = document.querySelector("#quiz-status");

        status.textContent = `Quiz submitted. You selected ${selectedCount} answer${
          selectedCount === 1 ? "" : "s"
        }.`;
      });
    </script>
  </body>
</html>
